const countServiceListings = `-- name: CountServiceListings :one
SELECT COUNT(*)
FROM contents c
JOIN service_listing_meta sm ON sm.content_id = c.id
WHERE c.content_type = 'service_listing'
  AND c.deleted_at IS NULL
  AND c.status = COALESCE($1, 'published')
  AND ($2::uuid IS NULL OR sm.destination_space_id = $2::uuid)
  AND ($3::uuid IS NULL OR sm.city_space_id = $3::uuid)
  AND ($4::text IS NULL OR sm.service_category = $4::text)
  AND ($5::text IS NULL OR $5::text = ANY(sm.origin_communities))
  AND ($6::bool IS NULL OR sm.is_verified = $6::bool)
  AND ($7::text IS NULL OR sm.listing_kind = $7::text)
  AND ($8::bigint IS NULL OR sm.price_amount <= $8::bigint)
  AND ($9::date IS NULL OR sm.available_from IS NULL OR sm.available_from >= $9::date)
  AND ($10::text IS NULL OR c.title ILIKE '%' || $10::text || '%')
`

