const decrementDepartureBookedCount = `-- name: DecrementDepartureBookedCount :execrows
UPDATE service_package_departures
SET booked_count = GREATEST(0, booked_count - $1),
    status = CASE
        WHEN status = 'full' AND (capacity IS NULL OR booked_count - $1 < capacity)
            THEN 'open'
        ELSE status
    END
WHERE id = $2
`

type DecrementDepartureBookedCountParams struct {
	PartySize int32       `json:"party_size"`
	ID        pgtype.UUID `json:"id"`
}

func (q *Queries) DecrementDepartureBookedCount(ctx context.Context, arg DecrementDepartureBookedCountParams) (int64, error) {
	result, err := q.db.Exec(ctx, decrementDepartureBookedCount, arg.PartySize, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

